<script setup>import AppShell from'../Layouts/AppShell.vue';import PageHeader from'../Components/PageHeader.vue';import StateCard from'../Components/StateCard.vue';import{Head,router}from'@inertiajs/vue3';import{reactive}from'vue';const props=defineProps({summary:Object,groups:Array,filters:Object,availableGroups:Array,exportUrl:String}),form=reactive({from:props.filters?.from||'',to:props.filters?.to||'',group_id:props.filters?.group_id||''});const bytes=v=>new Intl.NumberFormat('en-IN',{style:'unit',unit:'megabyte',maximumFractionDigits:1}).format((v||0)/1048576),apply=()=>router.get('/analytics',form,{preserveState:true,replace:true}),query=()=>new URLSearchParams(Object.entries(form).filter(([,v])=>v!==''&&v!==null)).toString()</script>
<template><AppShell><Head title="Analytics"/><div class="lp-page"><PageHeader eyebrow="Studio performance" title="Analytics" description="Permission-scoped, plan-controlled metrics from your LensPic Groups."/><form class="lp-card mt-6 grid gap-4 p-5 sm:grid-cols-2 xl:grid-cols-4" @submit.prevent="apply"><label class="form-label">From<input v-model="form.from" type="date" class="form-input mt-2"></label><label class="form-label">To<input v-model="form.to" type="date" class="form-input mt-2"></label><label class="form-label">Group<select v-model="form.group_id" class="form-input mt-2"><option value="">All permitted Groups</option><option v-for="group in availableGroups" :key="group.id" :value="group.id">{{group.name}}</option></select></label><div class="flex items-end gap-2"><button class="btn-primary" type="submit">Apply filters</button><a :href="`${exportUrl}?${query()}`" class="btn-ghost">Export CSV</a></div></form><section class="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><div v-for="(value,key) in summary" :key="key" class="lp-card p-5"><p class="text-sm capitalize text-slate-500">{{key.replaceAll('_',' ')}}</p><p class="mt-2 text-3xl font-bold">{{key==='storage_bytes'?bytes(value):value}}</p></div></section><StateCard v-if="!groups.length" class="mt-6" title="No analytics yet" message="No Groups match the current permission scope and filters."/><div v-else class="lp-table-wrap mt-6"><table class="lp-table"><thead><tr><th>Group</th><th>Photos</th><th>Participants</th><th>Updated</th></tr></thead><tbody><tr v-for="group in groups" :key="group.id"><td><a :href="`/groups/${group.id}`" class="font-semibold text-indigo">{{group.name}}</a></td><td>{{group.photos_count}}</td><td>{{group.members_count}}</td><td>{{new Date(group.updated_at).toLocaleDateString('en-IN')}}</td></tr></tbody></table></div></div></AppShell></template>
